<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Symfony\Component\Process\Process;
class MySqlBackupService {
 private function directory():string{$path=storage_path('app/private/backups');if(!is_dir($path))mkdir($path,0700,true);return $path;}
 private function admin():\PDO{$c=config('database.connections.mysql');$path=getenv('LOCALAPPDATA').'/PLPEnrollment/runtime/admin.json';$local=in_array($c['host'],['127.0.0.1','localhost'])&&(int)$c['port']===3307&&is_file($path);$credentials=$local?json_decode(file_get_contents($path),true):null;return new \PDO('mysql:host='.$c['host'].';port='.$c['port'].';charset=utf8mb4',$local?'root':$c['username'],$local?$credentials['password']:$c['password'],[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION]);}
 private function binary(string $name):string{$configured=config('enrollment.'.($name==='mariadb-dump'?'dump_binary':'client_binary'));if($configured)return $configured;$bundled=getenv('LOCALAPPDATA').'/PLPEnrollment/runtime/mariadb-11.4.9-winx64/bin/'.$name.'.exe';return is_file($bundled)?$bundled:$name;}
 private function run(string $binary,array $args,?string $input=null,bool $admin=false):string{$c=config('database.connections.mysql');$path=tempnam($this->directory(),'client-');try{$password=$c['password'];$username=$c['username'];$adminPath=getenv('LOCALAPPDATA').'/PLPEnrollment/runtime/admin.json';if($admin&&in_array($c['host'],['127.0.0.1','localhost'])&&(int)$c['port']===3307&&is_file($adminPath)){$username='root';$password=json_decode(file_get_contents($adminPath),true)['password'];}$quote=fn($value)=>'"'.str_replace(['\\','"',"\n","\r"],['\\\\','\\"','\\n','\\r'],(string)$value).'"';file_put_contents($path,"[client]\nprotocol=tcp\nhost=".$quote($c['host'])."\nport=".(int)$c['port']."\nuser=".$quote($username)."\npassword=".$quote($password)."\n");@chmod($path,0600);$process=new Process(array_merge([$this->binary($binary),'--defaults-extra-file='.$path],$args),base_path());$process->setTimeout(180);if($input!==null)$process->setInput($input);$process->run();if(!$process->isSuccessful())throw new \RuntimeException('Database backup/restore command failed. Check the database connection and backup client installation.');return $process->getOutput();}finally{if(is_file($path))unlink($path);}}
 private function restore(string $sql):array{$target='plp_restore_check_'.bin2hex(random_bytes(8));$pdo=$this->admin();$pdo->exec("CREATE DATABASE `$target` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");try{$this->run('mariadb',['--binary-mode','--local-infile=0','--database='.$target],$sql,true);$counts=[];foreach($pdo->query("SHOW TABLES FROM `$target`")->fetchAll(\PDO::FETCH_COLUMN) as $table){$counts[$table]=(int)$pdo->query("SELECT COUNT(*) FROM `$target`.`$table`")->fetchColumn();$result=$pdo->query("CHECK TABLE `$target`.`$table`")->fetchAll(\PDO::FETCH_ASSOC);foreach($result as $row)if($row['Msg_type']==='error')throw new \RuntimeException('Restored table validation failed.');}ksort($counts);foreach(['users','students','cor_versions','migrations'] as $table)if(!array_key_exists($table,$counts))throw new \RuntimeException('Restored backup is missing required tables.');foreach($pdo->query("SELECT TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=".$pdo->quote($target).' AND REFERENCED_TABLE_NAME IS NOT NULL')->fetchAll(\PDO::FETCH_ASSOC) as $fk){$sql="SELECT count(*) FROM `$target`.`{$fk['TABLE_NAME']}` a LEFT JOIN `$target`.`{$fk['REFERENCED_TABLE_NAME']}` b ON a.`{$fk['COLUMN_NAME']}`=b.`{$fk['REFERENCED_COLUMN_NAME']}` WHERE a.`{$fk['COLUMN_NAME']}` IS NOT NULL AND b.`{$fk['REFERENCED_COLUMN_NAME']}` IS NULL";if($pdo->query($sql)->fetchColumn())throw new \RuntimeException('Restored foreign-key validation failed.');}return ['target'=>$target,'counts'=>$counts,'tables'=>count($counts)];}catch(\Throwable $error){$pdo->exec("DROP DATABASE `$target`");throw $error;}}
 public function create():string{$database=config('database.connections.mysql.database');if(!preg_match('/^[a-zA-Z0-9_]+$/',$database))throw new \RuntimeException('Invalid backup database name.');$sql=$this->run('mariadb-dump',['--single-transaction','--quick','--skip-lock-tables','--hex-blob','--skip-comments','--skip-add-locks','--no-tablespaces',$database]);$verified=$this->restore($sql);$this->admin()->exec('DROP DATABASE `'.$verified['target'].'`');$payload=['schema'=>3,'driver'=>'mysql','created_at'=>now()->toIso8601String(),'counts'=>$verified['counts'],'sha256'=>hash('sha256',$sql),'sql'=>$sql];$path=$this->directory().'/enrollment-'.now()->format('Ymd-His').'-'.bin2hex(random_bytes(4)).'.sql.enc';$encrypted=encrypt($payload);$handle=fopen($path,'x');try{if(fwrite($handle,$encrypted)!==strlen($encrypted))throw new \RuntimeException('Encrypted backup write failed.');}finally{fclose($handle);}if(decrypt(file_get_contents($path))!==$payload)throw new \RuntimeException('Written backup verification failed.');return $path;}
 public function verify(string $path):array{$payload=decrypt(file_get_contents($path));if(($payload['schema']??null)!==3||($payload['driver']??null)!=='mysql'||!isset($payload['sql'],$payload['sha256'],$payload['counts'])||!hash_equals($payload['sha256'],hash('sha256',$payload['sql'])))throw new \RuntimeException('Expected a valid MariaDB/MySQL backup.');$result=$this->restore($payload['sql']);if($result['counts']!==$payload['counts']){$this->admin()->exec('DROP DATABASE `'.$result['target'].'`');throw new \RuntimeException('Restored table counts differ from the backup manifest.');}return $result+['source_created_at'=>$payload['created_at']];}
}
